import json

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G:
        G[k] = [[int(x) for x in r] for r in rows]

inp = G['Demo pair 1 input']
out = G['Demo pair 1 output']

# Analyze component types
def get_comp_type(comp_set):
    rows_comp = set(c[0] for c in comp_set)
    cols_comp = set(c[1] for c in comp_set)
    min_r, max_r = min(rows_comp), max(rows_comp)
    min_c, max_c = min(cols_comp), max(cols_comp)

    row_counts = {}
    col_counts = {}
    for r, c in comp_set:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1

    is_t_horizontal = max(row_counts.values()) == 3
    is_t_vertical = max(col_counts.values()) == 3

    if is_t_horizontal:
        center_r = max(row_counts)
        singles = [(r, c) for r, c in comp_set if r != center_r]
        if singles:
            has_cell_above = any(s[0] == center_r - 1 for s in singles)
            has_cell_below = any(s[0] == center_r + 1 for s in singles)
            if has_cell_above:
                return 'T-up'
            return 'T-down'
    elif is_t_vertical:
        center_c = max(col_counts)
        singles = [(r, c) for r, c in comp_set if c != center_c]
        if singles:
            has_cell_left = any(s[1] == center_c - 1 for s in singles)
            has_cell_right = any(s[1] == center_c + 1 for s in singles)
            if has_cell_left:
                return 'T-left'
            return 'T-right'

    return 'unknown'

components = []
visited = set()
num_rows, num_cols = len(inp), len(inp[0])

for r in range(num_rows):
    for c in range(num_cols):
        if inp[r][c] == 2 and (r, c) not in visited:
            comp = set()
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                comp.add((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < num_rows and 0 <= nc < num_cols and inp[nr][nc] == 2 and (nr, nc) not in visited:
                        stack.append((nr, nc))
            components.append(comp)

print("Components with types:")
for i, comp in enumerate(components):
    typ = get_comp_type(comp)
    print(f"  {i}: {sorted(comp)}, type={typ}")

# Now let's align the input and output grids
# The output seems to be a compressed version
# Let's see if there's a spatial relationship

print("\nOutput grid:")
for row in out:
    print(row)

# Let's try different grid divisions
possible_divisions = [
    (5, 5),  # 5x5 cells
    (7, 7),  # not integer divide
    (3, 3),  # 3x3 blocks
    (4, 4),  # 4x4 blocks
]

print("\nTrying spatial mapping:")
for div_r, div_c in possible_divisions:
    if num_rows % div_r == 0 and num_cols % div_c == 0:
        print(f"\n{div_r}x{div_c} division (each cell is {num_rows//div_r}x{num_cols//div_c})")
        for output_r in range(div_r):
            row_output = []
            for output_c in range(div_c):
                start_r = output_r * (num_rows // div_r)
                start_c = output_c * (num_cols // div_c)
                end_r = start_r + num_rows // div_r
                end_c = start_c + num_cols // div_c

                count = 0
                for r in range(start_r, end_r):
                    for c in range(start_c, end_c):
                        if inp[r][c] == 2:
                            count += 1
                row_output.append(count)
            print(f"  [{output_r}]: {' '.join(map(str, row_output))}")

